    {showHelp && <div className="modal-backdrop" onClick={() => setShowHelp(false)}><section className="modal modal-narrow" role="dialog" aria-modal="true" aria-labelledby="help-title" onClick={e => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">STOCKWISE QUICK GUIDE</div><h2 id="help-title">A few useful shortcuts</h2><p>Get around your inventory faster.</p></div><button className="icon-btn" onClick={() => setShowHelp(false)}><X size={18} /></button></div><div className="help-steps"><div><kbd>Ctrl + K</kbd><span>Jump to product search</span></div><div><kbd>Filter</kbd><span>Narrow the catalog by category or stock status</span></div><div><kbd>···</kbd><span>Edit a product or record a stock movement</span></div><div><kbd>Stockwise AI</kbd><span>Ask a question using your current inventory data</span></div></div><div className="modal-actions"><button className="btn primary" onClick={() => setShowHelp(false)}>Got it</button></div></section></div>}
